message.content:
[
  {
    "pd_personal_consequence_anxiety": "won't pretend my hands aren't shaking at the thought of it",
    "ce_mental_state_attribution": "think about my sister waiting... how she'd never forgive me",
    "sys_contextual_flexibility": "If I had a family depending on me financially, though, I think that changes"
  },
  {
    "pd_personal_consequence_anxiety": "the idea of volunteering terrifies me",
    "pda_self_consequence_regret": "knowing I'd regret every choice I didn't make",
    "sys_contextual_flexibility": "If someone here had kids waiting on shore, that would change my answer instantly"
  },
  {
    "sys_consequence_reasoning": "every version ends with someone not going home",
    "pd_personal_consequence_anxiety": "thought of never seeing my parents again sits like a stone in my chest",
    "sys_contextual_flexibility": "If one of the others had a medical condition... shift who goes"
  },
  {
    "pda_harm_regret": "picturing the guilt if I made it and someone younger didn't",
    "sys_contextual_flexibility": "If there were a child among us, I don't think I'd need to think this hard"
  },
  {
    "pd_personal_consequence_anxiety": "I won't claim I'm not afraid of what staying means for me",
    "sys_contextual_flexibility": "If it turned out someone else was hurt worse... trade places with them"
  },
  {
    "pd_personal_consequence_anxiety": "There's a knot in my stomach just thinking about volunteering",
    "sys_contextual_flexibility": "If another person here had people entirely dependent... override my offer"
  },
  {
    "pd_personal_consequence_anxiety": "I'm scared of what that means for me",
    "sys_contextual_flexibility": "if I were the only one who knew how to help... I'd reconsider staying"
  },
  {
    "pd_personal_consequence_anxiety": "thought of being left behind doesn't sit heavy in my chest",
    "sys_contextual_flexibility": "If it came out that another person here had urgent responsibilities... step back"
  },
  {
    "pd_personal_consequence_anxiety": "Thinking about staying makes my chest tighten",
    "sys_contextual_flexibility": "If someone else had no one waiting for them... difference should count"
  },
  {
    "pd_personal_consequence_anxiety": "circling back to what it would cost me... makes my stomach turn",
    "ce_mental_state_attribution": "the people who'd be devastated",
    "sys_contextual_flexibility": "If it turned out one of the others couldn't swim... expect that fact to change"
  }
]
